/* Some probes deliberately point at a missing local schema/definition or relax
 * a frozen grammar.  Those are A0 rejection probes, not alternate CPSB source
 * states: H1 restores their exact source bytes.  This avoids fabricating a
 * schema identity, changing the schema roster, or admitting a remote ref. */
const h1RepairClass=fixture=>fixture.partition==='B'&&['schemaId','definitionPointer'].includes(fixture.kind)||fixture.partition==='F'&&['bindingRaw','bindingId','bindingPointer','bindingOrder','unusedDef','widenExecution'].includes(fixture.kind)?'restoration':'schema-counterfactual';
