const H0_VALIDATOR_BYTES=438375;
const H0_VALIDATOR_RAW_SHA256='65727edaa77d783dd0db33f70f57856240f7c732b7156fa8c76785aadf94546c';

const rebindSchemaRaws=async(root,packageRoot)=>{assert.ok(Array.isArray(root.schemaBindings),`H1 schema bindings exist`);for(const binding of root.schemaBindings){assert.equal(typeof binding?.locator,'string',`H1 schema binding locator`);const bytes=readFileSync(resolve(packageRoot,binding.locator));binding.rawSha256=await sha256(bytes);}};
const h1RestoresOriginalRoot=fixture=>h1RepairClass(fixture)==='restoration';
const assertH1Redigested=(async(root,before,fixture)=>{const id=fixture.mutationId,document=readJson(root,ROOT_FILE);for(const binding of document.schemaBindings){assert.ok(schemaFiles.includes(binding.locator),`${id}: H1 schema binding repair path`);assert.equal(binding.rawSha256,await sha256(readFileSync(resolve(root,binding.locator))),`${id}: H1 rebound schema raw ${binding.locator}`);}for(const row of document.futureRecordContracts.entries){const copy={...row};delete copy.contentDigest;assert.deepEqual(row.contentDigest,await digestRecord(`${PREFIX}/future-record-contract/${row.recordKind}`,copy),`${id}: H1 redigested descriptor ${row.recordKind}`);}for(const [component,suffix] of componentDomains){const aggregate=document.componentDigests.find(row=>row.component===component);assert.ok(aggregate,`${id}: H1 component aggregate ${component}`);assert.deepEqual(aggregate.digest,await digestRecord(`${PREFIX}/${suffix}`,componentValue(document[component])),`${id}: H1 redigested component ${component}`);}const body={...document};delete body.contentDigest;assert.deepEqual(document.contentDigest,await digestRecord(`${PREFIX}/root`,body),`${id}: H1 redigested root`);if(h1RestoresOriginalRoot(fixture)){assert.deepEqual(document.contentDigest,before.contentDigest,`${id}: H1 root digest restored`);assert.deepEqual(document,before,`${id}: H1 root restored exactly`);}else assertRepairChange(before.contentDigest,document.contentDigest,id,'root semantics');return document;});
const assertH1LocalSchemaRefs=(root,id)=>{const schemas=schemaFiles.map(locator=>strictCanonical(readFileSync(resolve(root,locator)),`${id}: local refs ${locator}`)),ids=new Set(schemas.map(schema=>schema.$id));const visit=node=>{if(Array.isArray(node)){node.forEach(visit);return;}if(!node||typeof node!=='object')return;if(typeof node.$ref==='string'){const target=node.$ref.split('#',1)[0];assert.equal(target===''||ids.has(target),true,`${id}: H1 local schema ref ${node.$ref}`);}Object.values(node).forEach(visit);};schemas.forEach(visit);};
const assertH1AjvOracle=(root,id)=>{const ajv=new Ajv2020({strict:false,allErrors:true,validateFormats:false}),schemas=schemaFiles.map(locator=>strictCanonical(readFileSync(resolve(root,locator)),`${id}: Ajv ${locator}`));assert.equal(schemas.length,18,`${id}: H1 eighteen schemas`);for(const schema of schemas)ajv.addSchema(schema);for(const schema of schemas)assert.doesNotThrow(()=>ajv.getSchema(schema.$id)??ajv.compile(schema),`${id}: H1 compile ${schema.$id}`);const document=strictCanonical(readFileSync(resolve(root,ROOT_FILE)),`${id}: H1 root`),validate=ajv.getSchema(`${SCHEMA_PREFIX}root.v1.schema.json`);assert.equal(typeof validate,'function',`${id}: H1 root validator`);assert.equal(validate(document),true,`${id}: H1 root acceptance ${JSON.stringify(validate.errors)}`);};
const assertH1RepairClosure=(root,before,fixture,{locators,repairClass})=>{const tree=walk(root),files=tree.filter(row=>row.kind==='file').map(row=>row.locator).sort(),dirs=['.',...tree.filter(row=>row.kind==='directory').map(row=>row.locator)].sort();assert.deepEqual(files,[...AUTHORED_FILES].sort(),`${fixture.mutationId}: H1 exact source closure`);assert.deepEqual(dirs,['.','schemas','test'],`${fixture.mutationId}: H1 exact directory closure`);assert.equal(tree.every(row=>row.kind==='file'||row.kind==='directory'),true,`${fixture.mutationId}: H1 no links or specials`);for(const locator of dirs){const stat=lstatSync(resolve(root,locator));assert.equal(stat.isDirectory()&&!stat.isSymbolicLink()&&(stat.mode&0o777)===0o755,true,`${fixture.mutationId}: H1 directory mode ${locator}`);}for(const locator of files){const stat=lstatSync(resolve(root,locator));assert.equal(stat.isFile()&&!stat.isSymbolicLink()&&stat.nlink===1&&(stat.mode&0o777)===0o644,true,`${fixture.mutationId}: H1 file mode/link ${locator}`);}const repairs=new Set(locators),allowed=new Set([ROOT_FILE,changedLocator(fixture),...repairs]);if(repairClass==='restoration'){for(const locator of AUTHORED_FILES)assert.equal(readFileSync(resolve(root,locator)).equals(before[locator]),true,`${fixture.mutationId}: H1 source restored exactly`);return;}for(const locator of repairs)assert.equal(readFileSync(resolve(root,locator)).equals(before[locator]),false,`${fixture.mutationId}: H1 repair locator changed ${locator}`);for(const locator of AUTHORED_FILES){const changed=!readFileSync(resolve(root,locator)).equals(before[locator]);assert.equal(!changed||allowed.has(locator),true,`${fixture.mutationId}: H1 unrelated source drift ${locator}`);}};

for(const fixture of cases)test(`H1 ${fixture.mutationId} is an explicitly structural schema counterfactual or exact restoration`,async()=>{const root=mkdtempSync(resolve(packageParent,'.cpsb-h1-'));try{copySource(root);assertCloneBaseline(root);const before=Object.fromEntries(AUTHORED_FILES.map(locator=>[locator,readFileSync(resolve(root,locator))]));const primary=readJson(root,ROOT_FILE);mutate(fixture,root);assertOnePrimaryMutation(root,before,fixture);const mutated=readJson(root,ROOT_FILE),repair=h1Repair(fixture,root,primary,mutated,before);assert.ok(Array.isArray(repair.locators),`${fixture.mutationId}: H1 repair locator list`);assert.ok(['schema-counterfactual','restoration'].includes(repair.repairClass),`${fixture.mutationId}: H1 repair classification`);if(repair.repairClass==='schema-counterfactual'){const document=readJson(root,ROOT_FILE);await rebindSchemaRaws(document,root);await redigestCpsb(document);writeCanonical(root,ROOT_FILE,document);}await assertH1Redigested(root,primary,fixture);assertH1RepairClosure(root,before,fixture,repair);assertH1LocalSchemaRefs(root,fixture.mutationId);await assertSchemaReachability(root,`${fixture.mutationId}: H1`);assertH1AjvOracle(root,fixture.mutationId);}finally{rmSync(root,{recursive:true,force:true});}});

test('sealed coordinated H0/A1 uses frozen source literals and unchanged A0 validator',async()=>{assert.equal(readFileSync(resolve(packageRoot,ROOT_FILE)).length,H0_ROOT_BYTES,'literal H0 root bytes');assert.equal(sha256(readFileSync(resolve(packageRoot,ROOT_FILE))),H0_ROOT_RAW_SHA256,'literal H0 root raw');assert.equal(readFileSync(resolve(packageRoot,'validate-static.mjs')).length,H0_VALIDATOR_BYTES,'literal H0 validator bytes');assert.equal(sha256(readFileSync(resolve(packageRoot,'validate-static.mjs'))),H0_VALIDATOR_RAW_SHA256,'literal H0 validator raw');const h0=await cloneSealed();let staleFixture,a1;try{await assertH1Oracle(h0,'coherent H0');assertH1AjvOracle(h0.root,'coherent H0');assert.deepEqual(validateStatic({packageRoot:h0.root,...h0.pin}),{files:29,directories:3,schemaCount:18,futureRecordSchemaCount:11,totalRecordCount:0,rootContentDigest:h0.document.contentDigest.value,unsealed:false},'genuine production H0 sealed positive');staleFixture=await cloneSealed();assert.equal(readFileSync(resolve(staleFixture.root,'validate-static.mjs')).equals(sourceBytes['validate-static.mjs']),true,'unchanged original A0 validator');await updateSameWidthRoot(staleFixture.root);const staleEnvelope=await writeEnvelope(staleFixture.root),staleAnchor=await buildAnchor(staleFixture.root,staleEnvelope,{rootRawSha256:H0_ROOT_RAW_SHA256,validatorRawSha256:H0_VALIDATOR_RAW_SHA256}),stalePin=await installAnchor(staleFixture.root,staleFixture.anchorRoot,staleAnchor);expectCpsb('CPSB_ANCHOR_RAW:root',()=>validateStatic({packageRoot:staleFixture.root,...stalePin}));a1=await cloneSealed();const {before}=await updateSameWidthRoot(a1.root);assert.equal(readFileSync(resolve(a1.root,'validate-static.mjs')).equals(sourceBytes['validate-static.mjs']),true,'A1 retains unchanged imported A0 validator');const a1Envelope=await writeEnvelope(a1.root),a1Anchor=await buildAnchor(a1.root,a1Envelope,{validatorRawSha256:H0_VALIDATOR_RAW_SHA256});a1.pin=await installAnchor(a1.root,a1.anchorRoot,a1Anchor);const finalRoot=await assertH1Oracle(a1,'coherent A1');assertH1AjvOracle(a1.root,'coherent A1');expectCpsb('CPSB_SCHEMA_COMPILE:semantic-fingerprint:schemas/root.v1.schema.json',()=>validateStatic({packageRoot:a1.root,...a1.pin}));const semantic={...finalRoot,schemaBindings:before.schemaBindings};delete semantic.componentDigests;delete semantic.contentDigest;const original={...before};delete original.componentDigests;delete original.contentDigest;assert.equal(leafDiffCount(original,semantic),1,'A1 no semantic drift beyond purpose');}finally{if(a1)removeClone(a1);if(staleFixture)removeClone(staleFixture);removeClone(h0);}});
